namespace ghidra.app.plugin.core.datamgr.actions;







using docking;
using docking.action;
using docking.widgets;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.app.plugin.core.datamgr.util;

public class DeleteAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public DeleteAction(DataTypeManagerPlugin plugin) : base("Delete", plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Delete" }, null, "Edit"));
		setKeyBindingData(new KeyBindingData(KeyEvent.VK_DELETE, 0));

		setEnabled(true);
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		TreePath[] selectionPaths = getSelectionPaths(context);
		if (selectionPaths == null || selectionPaths.length == 0) {
			return false;
		}

		if (containsUndeletableNodes(selectionPaths)) {
			return false;
		}

		return true;
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		TreePath[] selectionPaths = getSelectionPaths(context);
		return canDelete(selectionPaths);
	}

	private TreePath[] getSelectionPaths(ActionContext context) {
		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		return selectionPaths;
	}

	private bool containsUndeletableNodes(TreePath[] selectionPaths) {
		foreach (TreePath path in selectionPaths) {
			DataTypeTreeNode node = (DataTypeTreeNode) path.getLastPathComponent();
			if (!node.canDelete() || (node is DataTypeStoreNode)) {
				return true;
			}
		}
		return false;
	}

	private bool canDelete(TreePath[] selectionPaths) {
		// only valid if all selected paths are of the correct type
		foreach (TreePath path in selectionPaths) {
			DataTypeTreeNode node = (DataTypeTreeNode) path.getLastPathComponent();
			if (!node.canCut()) {
				return false;
			}
		}
		return true;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		//@formatter:off
		int choice = OptionDialog.showYesNoDialogWithNoAsDefaultButton(null,
			"Confirm Delete Operation", 
				"Are you sure you want to delete selected\n" + 
				"data types and/or categories?\n\n" + 
				"Note: Changes may trigger the removal of related\n" + 
				"data types, components and defined data.");
		//@formatter:on
		if (choice != OptionDialog.OPTION_ONE) {
			return;
		}

		GTree gtree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		List<GTreeNode> nodeList = new(selectionPaths.length);
		foreach (TreePath path in selectionPaths) {
			nodeList.add((GTreeNode) path.getLastPathComponent());
		}
		plugin.getTool().execute(new DataTypeTreeDeleteTask(plugin, nodeList), 250);
	}
}
